// ---------------------------------------------------------------------------
// F1: consistent logical dump/restore for CONTAINERISED databases
// ---------------------------------------------------------------------------
/**
 * A database engine running INSIDE a container keeps its data in a named Docker
 * volume. Blindly `rsync`ing `/var/lib/docker/volumes/<v>/_data` while the
 * source container is still writing produces a TORN datadir the target engine
 * may fail to recover — or, worse, silently recovers minus the most recent
 * writes. So for a RUNNING DB container we take a CONSISTENT logical dump on the
 * source, skip the hot copy of its datadir volume, let the target engine init a
 * fresh empty datadir from its own env, and restore the dump after it is up.
 */
export type DbEngine = "postgres" | "mysql" | "mariadb" | "mongo";

/**
 * Classify a container image (basename, ignoring registry/tag/digest) as a
 * known DB engine and report where that engine keeps its datadir. Mirrors the
 * stateful regex the empty-volume guards use, but resolves the SPECIFIC engine
 * so the right dump/restore tool and datadir are chosen. `null` ⇒ not a DB we
 * know how to dump (leave it to the existing hot-copy path).
 */
export function dbEngineInfo(
  image: string
): { engine: DbEngine; datadir: string; ext: string; label: string } | null {
  const base = (image.split("@")[0].split(":")[0].split("/").pop() || "").toLowerCase();
  if (/postgres/.test(base)) return { engine: "postgres", datadir: "/var/lib/postgresql/data", ext: "pgdump", label: "PostgreSQL" };
  if (/mariadb/.test(base)) return { engine: "mariadb", datadir: "/var/lib/mysql", ext: "sql", label: "MariaDB" };
  if (/mysql/.test(base)) return { engine: "mysql", datadir: "/var/lib/mysql", ext: "sql", label: "MySQL" };
  if (/mongo/.test(base)) return { engine: "mongo", datadir: "/data/db", ext: "mongoarchive", label: "MongoDB" };
  return null;
}

/**
 * The consistent logical dump run ON THE SOURCE via `docker exec`. Emitted as a
 * STREAMED script (never argv), so the container name is the only interpolated
 * value (CONTNAME_RE-validated by the caller) and the superuser password is
 * NEVER handled by this process, NEVER placed in argv and NEVER logged: it is
 * referenced BY NAME inside the container's own shell (`"$POSTGRES_PASSWORD"`),
 * where docker exec has already made the container's configured env present.
 * The single quotes below are safe precisely because `onSourceScript` streams
 * this over stdin (`ssh … sh -s < file`) rather than wrapping it in argv quotes.
 * Pure READS (pg_dumpall/mysqldump/mongodump) — passes `assertSourceReadOnly`.
 */
export function containerDbDumpScript(priv: string, container: string, engine: DbEngine): string {
  let cmd: string;
  if (engine === "postgres") {
    cmd =
      "$PRIV docker exec " + container +
      " sh -c 'PGPASSWORD=\"${POSTGRES_PASSWORD:-}\" pg_dumpall -U \"${POSTGRES_USER:-postgres}\"'";
  } else if (engine === "mongo") {
    cmd =
      "$PRIV docker exec " + container +
      " sh -c 'if [ -n \"${MONGO_INITDB_ROOT_USERNAME:-}\" ]; then " +
      "mongodump --archive --username \"$MONGO_INITDB_ROOT_USERNAME\" --password \"${MONGO_INITDB_ROOT_PASSWORD:-}\" --authenticationDatabase admin; " +
      "else mongodump --archive; fi'";
  } else {
    // mysql / mariadb — MYSQL_PWD is read by mysqldump from the env, so the
    // password never appears on its command line.
    cmd =
      "$PRIV docker exec " + container +
      " sh -c 'MYSQL_PWD=\"${MYSQL_ROOT_PASSWORD:-${MARIADB_ROOT_PASSWORD:-}}\" " +
      "mysqldump -u root --all-databases --single-transaction --routines --triggers --events'";
  }
  return ["export LC_ALL=C", 'PRIV="' + priv + '"', cmd, ""].join("\n");
}

