/**
 * A readiness probe for the engine inside the TARGET container. Runs on the
 * target; exits 0 once the engine accepts connections. Password referenced by
 * name inside the container's shell — never argv, never logged. Built by string
 * concatenation (NOT a template literal) so the shell `${…}` expansions are
 * emitted verbatim. `container` is CONTNAME_RE-validated by the caller.
 */
export function containerDbReadyCommand(container: string, engine: DbEngine): string {
  if (engine === "postgres") {
    return "docker exec " + container +
      " sh -c 'PGPASSWORD=\"${POSTGRES_PASSWORD:-}\" pg_isready -U \"${POSTGRES_USER:-postgres}\" -q'";
  }
  if (engine === "mongo") {
    return "docker exec " + container +
      " sh -c 'mongosh --quiet --eval \"db.adminCommand({ping:1})\" >/dev/null 2>&1 || " +
      "mongo --quiet --eval \"db.adminCommand({ping:1})\" >/dev/null 2>&1'";
  }
  return "docker exec " + container +
    " sh -c 'MYSQL_PWD=\"${MYSQL_ROOT_PASSWORD:-${MARIADB_ROOT_PASSWORD:-}}\" mysqladmin -u root ping >/dev/null 2>&1'";
}

/**
 * Restore a consistent dump into the TARGET container's freshly-initialised
 * engine. Runs on the target; the dump is streamed into `docker exec -i` over
 * stdin. Superuser password referenced by name inside the container — never
 * argv, never logged. `container` is CONTNAME_RE-validated and `dumpPath`/
 * `errPath` are engine work-dir paths built from validated components.
 */
export function containerDbRestoreCommand(container: string, engine: DbEngine, dumpPath: string, errPath: string): string {
  const tail = ` < ${dumpPath} 2> ${errPath}`;
  if (engine === "postgres") {
    return "docker exec -i " + container +
      " sh -c 'PGPASSWORD=\"${POSTGRES_PASSWORD:-}\" psql -U \"${POSTGRES_USER:-postgres}\"'" + tail;
  }
  if (engine === "mongo") {
    return "docker exec -i " + container +
      " sh -c 'if [ -n \"${MONGO_INITDB_ROOT_USERNAME:-}\" ]; then " +
      "mongorestore --archive --drop --username \"$MONGO_INITDB_ROOT_USERNAME\" --password \"${MONGO_INITDB_ROOT_PASSWORD:-}\" --authenticationDatabase admin; " +
      "else mongorestore --archive --drop; fi'" + tail;
  }
  return "docker exec -i " + container +
    " sh -c 'MYSQL_PWD=\"${MYSQL_ROOT_PASSWORD:-${MARIADB_ROOT_PASSWORD:-}}\" mysql --force -u root'" + tail;
}

